# Build grid with CORRECT diagonal positions
final_grid = [[0]*15 for _ in range(15)]

# Ones on diagonal
for r, c in [(0, 0), (3, 3), (6, 6)]:
    final_grid[r][c] = 1

# Twos on diagonal starting at (last_one + gap), stepping by gap
# last_one = row 6, gap = 3, so start at 6+3=9
twos_start_row = 9
step = 3
for r in range(twos_start_row, 15, step):
    if r <= 14:  # within bounds
        final_grid[r][r] = 2  # IMPORTANT: COLUMN MUST MATCH ROW!

print("Non-zero entries:")
for r in range(15):
    for c in range(15):
        if final_grid[r][c] > 0:
            print(f"Row {r}, Col {c}: value = {final_grid[r][c]}")

print("\nFull grid:")
for r in range(15):
    print(final_grid[r])
